from typing import List


class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        weights = set()

        for a, b, w in edges:
            rev[b].append((a, w))
            weights.add(w)

        if not weights:
            return -1

        def can(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                node = stack.pop()
                for nxt, w in rev[node]:
                    if w <= limit and not seen[nxt]:
                        seen[nxt] = True
                        count += 1
                        stack.append(nxt)
            return count == n

        sorted_weights = sorted(weights)
        if not can(sorted_weights[-1]):
            return -1

        lo, hi = 0, len(sorted_weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if can(sorted_weights[mid]):
                hi = mid
            else:
                lo = mid + 1

        return sorted_weights[lo]
